    BooksController_createVersion: {
        parameters: {
            query?: {
                /** @description Where the entries come from: the journal (the diary, date range and archive rules below), a saved search (its stored filters), or hand-picked entries */
                source?: "journal" | "savedSearch" | "entries";
                /** @description Saved search whose filters select the entries (source=savedSearch) */
                savedSearchId?: number;
                /** @description Comma-separated IDs of the hand-picked entries (source=entries), at most 500 */
                entryIds?: string;
                /** @description Diary ID to build a journal book from (source=journal) */
                diaryId?: number;
                /** @description Book output format */
                format?: "pdf" | "epub" | "html" | "md";
                /** @description Book title (defaults to the diary or saved search name) */
                title?: string;
                /** @description Author name shown on the title page (defaults to the username) */
                author?: string;
                /** @description A short dedication on its own page after the title page; line breaks are kept. Longer than 300 characters (once trimmed) is a 400 BOOK_DEDICATION_TOO_LONG */
                dedication?: string;
                /** @description A short epigraph (a quotation and who said it) on its own page after the dedication; line breaks are kept. Longer than 500 characters (once trimmed) is a 400 BOOK_EPIGRAPH_TOO_LONG */
                epigraph?: string;
                /** @description End the book with an "About this book" page: the dates of its first and last entries, how many entries it holds, and the writer’s day it was made on (`today`) */
                closingPage?: boolean;
                /** @description Journal books: only include entries on or after this date (YYYY-MM-DD) */
                dateFrom?: string;
                /** @description Journal books: only include entries on or before this date (YYYY-MM-DD) */
                dateTo?: string;
                /** @description Chapter ordering: alphabetical, by entry count, or by first entry date */
                chapterOrder?: "alpha" | "entries" | "chrono";
                /** @description Chapter grouping mode: tags, calendar years, calendar months, one chapter for the whole book, or one per life era (each entry in the shortest era that covers its date; includeUntagged adds an "Other" chapter for entries outside every era) */
                chapterMode?: "tags" | "year" | "month" | "single" | "eras";
                /** @description Place entries in every matching tag chapter, or only in their first tag chapter */
                tagScope?: "all" | "first";
                /** @description Comma-separated list of tags to use as chapters (defaults to all tags) */
                tags?: string;
                /** @description Add a final chapter for entries without tags (tag chapters) or outside every life era (era chapters) */
                includeUntagged?: boolean;
                /** @description Show entry dates inside chapters */
                includeDates?: boolean;
                /** @description Include a table of contents */
                includeToc?: boolean;
                /** @description Use AI to weave each chapter's entries into flowing prose (requires a configured AI key) */
                narrative?: boolean;
                /** @description Add AI-generated introductions and summaries around each chapter */
                chapterFraming?: boolean;
                /** @description AI weaving mode for narrative chapters */
                weavingMode?: "strict" | "creative";
                /** @description Color palette for the generated book cover */
                coverTheme?: "classic" | "ocean" | "forest" | "rose";
                /** @description Interior theme of the pages: standard (sans-serif type, the usual margins, chapters opening at the top of their page), elegant (serif type, wider margins, chapters opening a quarter of the way down, centred under a short rule, photos narrower and centred) or large-print (larger type with more space between lines, ragged right, taller photos). It sets the PDF's pages and, through their style sheet, the HTML and EPUB; Markdown has no layout of its own */
                interiorTheme?: "standard" | "elegant" | "large-print";
                /** @description Embed eligible image attachments from entries in the generated book */
                embedImages?: boolean;
                /** @description The writer’s own day (the UTC day or the one before or after it): the book’s date and file name, and the end of an ongoing life era; the server’s UTC day when left out */
                today?: string;
            };
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                "multipart/form-data": {
                    /** Format: binary */
                    coverImage?: string;
                };
            };
        };
        responses: {
            /** @description Metadata for the newly generated immutable book version */
            201: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "id": 1,
                     *       "versionNumber": 1,
                     *       "title": "June reflections",
                     *       "author": "example",
                     *       "format": "pdf",
                     *       "filename": "Daily Journal",
                     *       "chapterCount": 3,
                     *       "entryCount": 3,
                     *       "addedEntryCount": 3,
                     *       "addedChapterTitles": [
                     *         "June reflections"
                     *       ],
                     *       "source": {
                     *         "kind": "savedSearch",
                     *         "savedSearchId": 4,
                     *         "savedSearchName": "Family favorites"
                     *       },
                     *       "createdAt": "2026-06-24T10:00:00.000Z"
                     *     }
                     */
                    "application/json": components["schemas"]["BookVersionResponseDto"];
                };
            };
            /** @description FEATURE_DISABLED: the `bookConverter` feature is turned off on this server */
            503: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "statusCode": 503,
                     *       "message": "FEATURE_DISABLED: the `bookConverter` feature is turned off on this server",
                     *       "error": "Service Unavailable",
                     *       "code": "SERVICE_UNAVAILABLE"
                     *     }
                     */
                    "application/json": components["schemas"]["ApiErrorResponse"];
                };
            };
        };
    };
